contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We take an amount to send as payment and call play().
    // The test checks behavior for any amount.
    function run(uint amount) public payable {
        // ensure this contract has enough balance to send
        require(address(this).balance >= amount);

        // Read observables before the call
        address bankBefore = c.bank();
        uint potBefore = c.pot();
        uint balanceCBefore = address(c).balance;
        uint balanceThisBefore = address(this).balance;

        bool reverted;
        // perform the state-changing call on c
        try c.play{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read observables after the call
        address bankAfter = c.bank();
        uint potAfter = c.pot();
        uint balanceCAfter = address(c).balance;
        uint balanceThisAfter = address(this).balance;
        uint balanceBankAfter = bankAfter.balance;

        // General rule asserted below:
        // - If amount != TICKET_AMOUNT (10) the call must revert and no state/balance changes occur on c.
        // - If amount == TICKET_AMOUNT then the call must not revert and either:
        //    * pot increases by amount (caller did not win): potAfter == potBefore + amount and no transfer to bank; OR
        //    * pot becomes zero (caller won): potAfter == 0 and bank received exactly FEE_AMOUNT (1) from c and caller received the rest.
        // We cannot reference TICKET_AMOUNT/FEE_AMOUNT directly, so we express the rule relative to observed balances and pot.

        assert(
            // bank address doesn't change
            bankBefore == bankAfter
            && (
                // Case: call reverted when amount not equal to ticket amount -> no changes to c's observable state or balances
                (reverted
                    && potAfter == potBefore
                    && balanceCAfter == balanceCBefore
                    && balanceThisAfter == balanceThisBefore
                )
                ||
                // Case: call did not revert -> amount must have been accepted as a ticket and observable effects follow
                (!reverted
                    && (
                        // Either pot increased by exactly the sent amount (no winner branch executed)
                        (potAfter == potBefore + amount
                            && balanceCAfter == balanceCBefore + amount
                            && balanceThisAfter == balanceThisBefore - amount
                        )
                        ||
                        // Or winner branch executed: pot became zero, contract's balance decreased by (potBefore + amount) and bank got FEE (observed as bank balance increase), caller got potBefore + amount - fee
                        (potAfter == 0
                            && balanceCAfter == balanceCBefore + amount - (potBefore + amount) // equals 0
                            && balanceThisAfter == balanceThisBefore - amount + (potBefore + amount - (balanceBankAfter - bankBefore.balance))
                            && (balanceBankAfter > bankBefore.balance) // bank received something
                        )
                    )
                )
            )
        );
    }

    // receive to accept refunds/transfers if needed
    receive() external payable {}
}

